package com.example.user_service.configuration;
import com.example.user_service.common.ApiErrorResponse; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import tools.jackson.databind.json.JsonMapper; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.List; import java.util.UUID;
@Component public class InternalApiFilter extends OncePerRequestFilter {
 private final byte[] expected; private final JsonMapper mapper;
 public InternalApiFilter(@Value("${user-service.internal-token:}") String token,JsonMapper mapper){this.expected=token.getBytes(StandardCharsets.UTF_8);this.mapper=mapper;}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if(!req.getRequestURI().startsWith("/internal/")){chain.doFilter(req,res);return;}byte[] supplied=String.valueOf(req.getHeader("X-Internal-Token")).getBytes(StandardCharsets.UTF_8);if(expected.length==0||!MessageDigest.isEqual(expected,supplied)){res.setStatus(401);res.setContentType(MediaType.APPLICATION_JSON_VALUE);String trace=UUID.randomUUID().toString();res.setHeader("X-Correlation-ID",trace);mapper.writeValue(res.getOutputStream(),new ApiErrorResponse("UNAUTHORIZED","Valid internal service credential is required",List.of(),trace));return;}chain.doFilter(req,res);}
}
